import {reflectionTopics,topicResponses,responseCounts,reflectionChoices,reflectionQuestions,SENSITIVE_INDEX} from './reflection60-model.mjs';
import {displayLanguage,languageName} from './mental-language.mjs';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const say=(l,en,hi)=>l==='hi'?hi:en;


function topicBars(answers,l,interactive=false,selected='structure'){
 return `<div class="mh-topic-bars">${reflectionTopics.map(t=>{const s=topicResponses(answers,t);return `<${interactive?'button':'div'} class="mh-topic-row" ${interactive?`data-reflection-topic="${t.id}" aria-pressed="${selected===t.id}" aria-controls="mh-topic-reading"`:''}><span><strong>${esc(t[l])}</strong><b>${s.agreed}<small> / ${s.total} ${say(l,'agree','सहमत')}</small></b></span><span class="mh-topic-track"><i style="width:${s.disagreed/s.total*100}%" class="disagreed"></i><i style="width:${s.neutral/s.total*100}%" class="neutral"></i><i style="width:${s.agreed/s.total*100}%" class="agreed"></i></span><small>${say(l,`${s.disagreed} disagree · ${s.neutral} neutral · ${s.agreed} agree`,`${s.disagreed} असहमत · ${s.neutral} तटस्थ · ${s.agreed} सहमत`)}</small></${interactive?'button':'div'}>`;}).join('')}</div>`;
}
function distribution(answers,l){const counts=responseCounts(answers),labels=reflectionChoices(l);return `<div class="mh-answer-distribution">${counts.map((count,i)=>`<div><span>${esc(labels[i])}</span><span class="mh-distribution-track"><i style="width:${count/59*100}%"></i></span><b>${count}</b></div>`).join('')}</div>`;}
export function topicReading(answers,id,l='en'){l=displayLanguage(l);const t=reflectionTopics.find(t=>t.id===id)||reflectionTopics[0],s=topicResponses(answers,t);return `<h3>${esc(t[l])}</h3><p>${say(l,`You agreed with ${s.agreed} of the ${s.total} statements in this topic. This describes your selections, not a level of illness or a personality type.`,`इस विषय के ${s.total} statements में से ${s.agreed} से आप सहमत थे। यह आपके चुने जवाब बताता है, बीमारी का स्तर या personality type नहीं।`)}</p><p>${say(l,t.enStep,t.hiStep)}</p>`;}
export function reflectionSample(view='snapshot',l='en'){
 l=displayLanguage(l);const sample=Array.from({length:60},(_,i)=>[1,2,3,4,0][i%5]);sample[1]='skip';
 return `<div class="mh-sample-head"><span>✳ innerly.</span><span class="mh-badge">${say(l,'EXAMPLE · NOT YOUR RESULTS','उदाहरण · आपके नतीजे नहीं')}</span></div><h3>${say(l,view==='journey'?'A small next step.':view==='days'?'Your choices, at a glance.':'Patterns to reflect on.',view==='journey'?'एक छोटा अगला कदम।':view==='days'?'आपके जवाब, एक नज़र में।':'समझने के लिए कुछ तरीके।')}</h3>${view==='journey'?`<div class="mh-sample-reflection"><p>${say(l,'Closeness & social comfort','नज़दीकी और सामाजिक सहजता')}</p><strong>${say(l,'What helps you feel comfortable around someone?','किसी के साथ आपको सहज होने में क्या मदद करता है?')}</strong><p>${say(l,'One question to explore after noticing your responses.','अपने जवाब देखने के बाद सोचने के लिए एक सवाल।')}</p></div>`:view==='days'?distribution(sample,l):topicBars(sample,l)}<p class="mh-demo-foot">${say(l,'Illustrative responses only. No diagnosis or mental-health score.','केवल काल्पनिक जवाब। Diagnosis या mental-health score नहीं।')}</p>`;
}
export function reflectionReportMarkup(report,l='en',view='snapshot',selected='structure',saved=false){
 l=displayLanguage(l);const date=new Date(report.createdAt).toLocaleDateString(l,{day:'numeric',month:'long',year:'numeric'}),choices=reflectionChoices(l);
 return `<section class="mh-report mh-reflection-report"><div class="mh-report-heading"><p class="mh-kicker">${say(l,'YOUR REFLECTION','आपकी REFLECTION')} · ${date}</p><h1>${say(l,'A little more understanding.','खुद की थोड़ी बेहतर समझ।')}</h1><p>${say(l,'Your answers are a starting point for reflection, not a label for who you are.','आपके जवाब खुद को समझने की शुरुआत हैं, आपकी पहचान का ठप्पा नहीं।')}</p></div><div class="mh-reflection-summary"><strong>60</strong><div><h2>${say(l,'Statements explored','Statements पूरे हुए')}</h2><p>${say(l,'Seven topics to explore. Choose one that matters to you.','सोचने के लिए सात विषय। जो आपके लिए ज़रूरी हो, उसे चुनें।')}</p></div></div><p class="mh-report-limit">${say(l,'This custom questionnaire has no validated scoring key. These charts count your responses; they do not diagnose a condition, assess immediate safety or measure a percentage of mental health.','इस custom questionnaire की validated scoring key नहीं है। Charts आपके जवाब गिनते हैं; diagnosis, तत्काल सुरक्षा की जाँच या mental health का प्रतिशत नहीं बताते।')}</p>${report.language!=='en'?`<p class="mh-translation-note">${say(l,`Question language: ${languageName(report.language)}. Translations are editorial and have not been independently validated.`,`सवालों की भाषा: ${languageName(report.language)}। अनुवाद संपादकीय हैं, उनका स्वतंत्र validation नहीं हुआ है।`)}</p>`:''}
 <div class="mh-report-visual"><div class="mh-demo-tabs" role="group" aria-label="${say(l,'Your report views','Report के नज़रिए')}">${[['snapshot','Patterns to explore','समझने के विषय'],['days','Your responses','आपके जवाब'],['journey','A small next step','एक छोटा अगला कदम']].map(([v,en,hi])=>`<button data-report-view="${v}" aria-pressed="${v===view}">${say(l,en,hi)}</button>`).join('')}</div>
 ${view==='snapshot'?`${topicBars(report.answers,l,true,selected)}<div id="mh-topic-reading" class="mh-topic-reading" aria-live="polite">${topicReading(report.answers,selected,l)}</div>`:view==='days'?`${distribution(report.answers,l)}<details class="mh-response-details"><summary>${say(l,'Read each statement and response','हर statement और जवाब देखें')}</summary><ol>${reflectionQuestions.map((q,i)=>i===SENSITIVE_INDEX?'':`<li value="${i+1}"><p>${esc(q[l])}</p><strong>${esc(choices[report.answers[i]])}</strong></li>`).join('')}</ol></details>`:`<div class="mh-next-steps"><p>${say(l,'Choose a topic for a reflection prompt. These are optional prompts, not a treatment plan.','सोचने के लिए एक विषय चुनें। ये वैकल्पिक prompts हैं, इलाज की योजना नहीं।')}</p><div>${reflectionTopics.map(t=>`<article><h3>${esc(t[l])}</h3><p>${esc(say(l,t.enStep,t.hiStep))}</p></article>`).join('')}</div></div>`}
 <p class="mh-chart-note">${say(l,'Charts include 59 statements. The optional self-harm statement is kept out of charts and aggregates. Higher agreement is not better or worse; topics are editorial groupings, not clinical scales.','Charts में 59 statements हैं। वैकल्पिक self-harm सवाल charts और कुल आँकड़ों से बाहर है। ज़्यादा सहमति बेहतर या खराब नहीं है; विषय संपादकीय समूह हैं, clinical scales नहीं।')}</p></div>
 <details class="mh-method"><summary>${say(l,'What this reflection can tell you','इस reflection से क्या समझ सकते हैं')}</summary><p>${say(l,'It shows which statements you agreed with and gives you topics to discuss. Enjoying solitude, planning carefully or having an unusual idea does not by itself mean a mental-health condition. No total score, disorder label, clinical threshold or comparison with other people is calculated.','यह दिखाता है कि किन statements से आप सहमत थे और बातचीत के विषय देता है। अकेलापन पसंद करना, सावधानी से योजना बनाना या अलग विचार रखना अपने-आप में mental-health condition नहीं है। कोई total score, disorder label, clinical threshold या दूसरों से तुलना नहीं निकाली जाती।')}</p><p>${say(l,'If something feels distressing, persistent or affects your daily life, a qualified mental-health professional can help you understand it. Earlier screening reports keep their original questionnaire and are not comparable with this reflection.','कोई बात परेशान करे, बनी रहे या रोज़मर्रा को प्रभावित करे तो योग्य mental-health professional उसे समझने में मदद कर सकता है। पुरानी screening reports अपने मूल questionnaire के साथ रहती हैं; उनकी इस reflection से तुलना नहीं की जाती।')}</p></details>
 <div class="mh-report-actions"><button class="mh-primary" data-action="save">${say(l,saved?'Saved on this device':'Save on this device',saved?'इस device पर सेव है':'इस device पर सेव करें')}</button><button class="mh-secondary" data-action="print">${say(l,'Print / save PDF','Print / PDF सेव करें')}</button><button class="mh-link" data-action="begin">${say(l,'Start My Test','अपना टेस्ट शुरू करें')}</button></div><p class="mh-footnote">${say(l,'Your full reflection report is free for now.','आपकी पूरी reflection report अभी मुफ़्त है।')}</p><div id="mh-report-status" class="mh-form-message" role="status"></div></section>`;
}
